import csv,re,collections,json
queue={x['variant_key']:x for x in csv.DictReader(open('outputs/stage5_score_queue.csv'))};byid={x['input_label']:f"{x['chr']}:{x['position_GRCh38']}:{x['reference_allele']}>{x['alternate_allele']}" for x in csv.DictReader(open('outputs/stage5_variant_input_manifest.csv')) if x['status'] in ('reference_verified_study_pair','reference_matches_GRCh38')}
rows=[]
for x in csv.DictReader(open('outputs/stage3_gtex_v10_candidate_qtls.csv')):
 match=re.fullmatch(r'(chr\d+)_(\d+)_([ACGT]+)_([ACGT]+)_b38',x['gtex_variant_id']);assert match,x['gtex_variant_id'];c,p,ref,alt=match.groups();key=f'{c}:{p}:{ref}>{alt}'
 rows.append({'variant_key':key,'variant_label':x['candidate'],'gene_id':x['gencode_id'].split('.')[0],'gene_symbol':x['gene_symbol'],'tissue_or_cell':x['tissue'],'molecular_type':x['qtl_type'],'molecular_event':x['molecular_phenotype'],'effect_alt':x['normalized_effect_size'],'effect_se':'','p_value':x['p_value'],'credible_set_pip':'','source':'GTEx portal gtex_v10','dataset':'gtex_v10','variant_in_score_queue':key in queue,'interpretation':'ALT versus REF NES; v10 GTEx is not fully independent of model training. For splice event NES is event-specific and not directly comparable to unsigned gene-level max scorer.'})
for x in csv.DictReader(open('outputs/stage3_selected_molecular_qtl_ld_proxies.csv')):
 c,p,ref,alt=x['qtl_variant_grch38'].split('_');key=f'{c}:{p}:{ref}>{alt}'
 rows.append({'variant_key':key,'variant_label':x['proxy_reference_id'],'gene_id':x['gene_id'],'gene_symbol':x['source_gene_symbol'],'tissue_or_cell':x['tissue'],'molecular_type':'sQTL' if ':' in x['molecular_trait_id'] else 'eQTL','molecular_event':x['molecular_trait_id'],'effect_alt':x['qtl_beta_alt'],'effect_se':x['qtl_se'],'p_value':x['qtl_p_unadjusted'],'credible_set_pip':'','source':'eQTL Catalogue release 7 selected region','dataset':x['dataset'],'variant_in_score_queue':key in queue,'interpretation':'nominal QTL for LD proxy; GRCh37 to GRCh38 linkage by rsID/alleles, no per-variant independent liftover; QTL ALT effect is not index-marker direction; selected gene/tissue'})
for x in csv.DictReader(open('outputs/stage4_onek1k_candidate_credible_set_matches.csv')):
 c,p,ref,alt=x['qtl_variant_id'].split('_');key=f'{c}:{p}:{ref}>{alt}'
 rows.append({'variant_key':key,'variant_label':x['candidate'],'gene_id':x['gene_id'],'gene_symbol':'','tissue_or_cell':x['cell_population'],'molecular_type':'cell eQTL','molecular_event':x['molecular_trait_id'],'effect_alt':x['beta'],'effect_se':x['se'],'p_value':x['p_value'],'credible_set_pip':x['pip'],'source':'eQTL Catalogue release 7 OneK1K','dataset':x['dataset'],'variant_in_score_queue':key in queue,'interpretation':'cell QTL; independence from model training and disease GWAS must be assessed; no mediation inference'})
fields=list(rows[0]);
with open('outputs/stage5_measured_molecular_evidence.csv','w',newline='') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
count=collections.Counter((x['source'],str(x['variant_in_score_queue'])) for x in rows)
json.dump({'sources':{'GTEx_alt_effect':'https://www.gtexportal.org/home/faq','eQTL_catalogue_alt_effect':'https://www.ebi.ac.uk/eqtl/Data_access/','AlphaGenome_training':'https://github.com/google-deepmind/alphagenome_research'},'rows':len(rows),'counts':{'|'.join(k):v for k,v in count.items()},'interpretation':'candidate measurement inventory, not a model accuracy result; comparisons require exact allele, gene, tissue, output modality and effect direction; filtered significant GTEx endpoints are subject to selection'},open('outputs/stage5_measured_molecular_evidence_receipt.json','w'),indent=2)
print('rows',len(rows),'in queue',sum(x['variant_in_score_queue'] for x in rows),'by source',dict(count))
